#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: integrações do Mural ONDA (Google Drive, agendador e push).
# Rodar da raiz do repositório: bash scripts/wizard-integracoes.sh
# Parte A (etapas 1 a 8): antes do ticket 04 (Drive e agendador).
# Parte B (etapa 9): antes do ticket 12 (push). Pode ser feita depois, rodando de novo.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
ENV_FILE=".env.producao"   # ignorado pelo git (.env*); só guarda valores públicos e referências

# copiar "texto": põe o texto na área de transferência (nunca no disco).
copiar() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1
  fi
}

banner "Mural ONDA: integrações (Drive, agendador e push)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pontos de partida"
say "Este wizard usa o projeto do Supabase e o da Vercel que o wizard-deploy já criou."
say "Os segredos NUNCA são gravados em arquivo: vão pela área de transferência direto para a Vercel."
ask SUPABASE_PROJECT_REF "Project ref do Supabase de produção:"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
ask APP_URL "URL de produção do app (com https://):"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"
open_url "https://vercel.com/dashboard"
step "Abra o projeto do Mural ONDA → Settings → Environment Variables."
step "Copie o endereço dessa página (da barra do navegador)."
ask VERCEL_ENV_URL "Cole o endereço da página de variáveis de ambiente:"
write_env VERCEL_ENV_URL "$VERCEL_ENV_URL"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: projeto e API do Drive"
say "O Mural fala com o Drive por uma service account (uma conta de robô). Ela precisa de um projeto no Google Cloud."
open_url "https://console.cloud.google.com/projectcreate"
step "Nome do projeto: mural-onda. Clique em Create e espere terminar."
step "Na barra de cima, selecione o projeto mural-onda."
open_url "https://console.cloud.google.com/apis/library/drive.googleapis.com"
step "Clique em Enable (Ativar) na Google Drive API."
note "A API do Drive é gratuita; o projeto não precisa de cobrança."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: a conta de robô"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create"
step "Service account name: mural-onda-drive. Clique em Create and continue."
step "Não dê nenhum papel (Role) e não adicione usuários: o acesso virá do compartilhamento da pasta."
step "Clique em Done."
step "Na lista, copie o e-mail da conta (termina em .iam.gserviceaccount.com)."
ask GOOGLE_SERVICE_ACCOUNT_EMAIL "Cole o e-mail da service account:"
write_env GOOGLE_SERVICE_ACCOUNT_EMAIL "$GOOGLE_SERVICE_ACCOUNT_EMAIL"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: chave da conta de robô"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
step "Clique na conta mural-onda-drive → aba Keys → Add key → Create new key."
step "Escolha JSON e clique em Create. O navegador baixa um arquivo .json."
warn "Esse arquivo dá acesso à pasta do ministério. Não envie por e-mail nem mensagem."
note "Se aparecer \"Service account key creation is disabled\", a política da organização bloqueia chaves; me avise."
say "Arraste o arquivo baixado para esta janela (ou cole o caminho) e pressione Enter."
ask CAMINHO_CHAVE "Caminho do arquivo .json:"
CAMINHO_CHAVE="${CAMINHO_CHAVE//\"/}"
CAMINHO_CHAVE="${CAMINHO_CHAVE//\'/}"
if command -v cygpath >/dev/null 2>&1; then CAMINHO_CHAVE=$(cygpath -w "$CAMINHO_CHAVE" 2>/dev/null || printf '%s' "$CAMINHO_CHAVE"); fi
if SAIDA=$(node -e 'const j=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));if(j.type!=="service_account"||!j.private_key||!j.client_email)process.exit(2);process.stdout.write(j.client_email+"\n"+JSON.stringify(j))' "$CAMINHO_CHAVE" 2>/dev/null); then
  EMAIL_DA_CHAVE="${SAIDA%%$'\n'*}"
  CHAVE_COMPACTA="${SAIDA#*$'\n'}"
  if [[ "$EMAIL_DA_CHAVE" != "$GOOGLE_SERVICE_ACCOUNT_EMAIL" ]]; then
    warn "O e-mail da chave ($EMAIL_DA_CHAVE) não é o que você informou na etapa 3."
    SKIPPED+=("conferir se a chave JSON é da conta $GOOGLE_SERVICE_ACCOUNT_EMAIL")
  fi
  if copiar "$CHAVE_COMPACTA"; then
    say "✓ Chave lida e copiada para a área de transferência (numa linha só)."
  else
    warn "Não consegui usar a área de transferência. Abra o arquivo, copie o conteúdo inteiro e cole na Vercel."
    CHAVE_COMPACTA=""
  fi
  open_url "$VERCEL_ENV_URL"
  step "Add Environment Variable:"
  say "    Key:          GOOGLE_SERVICE_ACCOUNT_JSON"
  say "    Value:        cole (Ctrl+V)"
  say "    Environments: só Production (não marque Preview nem Development)"
  step "Ligue Sensitive e clique em Save."
  pause "Salvou na Vercel? Pressione Enter"
  copiar "" || true
  unset CHAVE_COMPACTA SAIDA
  if confirm "Apagar o arquivo baixado ($CAMINHO_CHAVE)? A chave já está na Vercel e dá para gerar outra."; then
    rm -f -- "$CAMINHO_CHAVE" && say "✓ Arquivo apagado."
  else
    warn "Guarde o arquivo em lugar seguro ou apague depois."
  fi
else
  warn "Não consegui ler uma chave de service account em: $CAMINHO_CHAVE"
  SKIPPED+=("variável GOOGLE_SERVICE_ACCOUNT_JSON na Vercel (chave JSON da service account)")
  pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Drive: compartilhar a pasta do ministério"
open_url "https://drive.google.com/drive/my-drive"
step "Clique com o botão direito na pasta do ministério → Compartilhar."
step "Adicione o e-mail: $GOOGLE_SERVICE_ACCOUNT_EMAIL"
step "Permissão: Editor. Desmarque \"Notificar pessoas\" e clique em Compartilhar."
step "Abra a pasta e copie o endereço da barra (termina em /folders/<ID>)."
ask DRIVE_PASTA_RAIZ_ID "Cole o endereço da pasta (ou só o ID):"
DRIVE_PASTA_RAIZ_ID="${DRIVE_PASTA_RAIZ_ID##*/folders/}"
DRIVE_PASTA_RAIZ_ID="${DRIVE_PASTA_RAIZ_ID%%[?/]*}"
write_env DRIVE_PASTA_RAIZ_ID "$DRIVE_PASTA_RAIZ_ID"
note "Só referência: o ID da pasta raiz é cadastrado em Configurações do Admin quando o ticket 04 estiver pronto."
note "As pastas criadas pelo app ficam com a service account como dona (ADR 0006); o ministério vê e usa normalmente."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: ligar a extensão pg_net"
say "O agendador do banco (pg_cron, que já roda aqui) usa a pg_net para chamar o app."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/database/extensions"
step "Busque por pg_net e ligue o interruptor."
step "Confirme que pg_cron já aparece ligado."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Supabase: chave de serviço (só no servidor)"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "Em Secret keys, revele e copie a chave (começa com sb_secret_). Se a tela só tiver as chaves antigas, é a service_role."
warn "Essa chave ignora todas as regras de acesso. Só a Vercel (servidor) pode tê-la: nunca NEXT_PUBLIC_, nunca no GitHub."
open_url "$VERCEL_ENV_URL"
step "Add Environment Variable:"
say "    Key:          SUPABASE_SERVICE_ROLE_KEY"
say "    Value:        cole a chave que você copiou"
say "    Environments: só Production"
step "Ligue Sensitive e clique em Save."
note "O wizard não pede nem guarda essa chave."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Segredo do agendador (CRON_SECRET)"
say "O banco chama o app com este segredo; o app só aceita chamadas que o tenham."
note "Rodar esta etapa de novo gera um segredo novo e troca nos dois lugares."
if confirm "Gerar o CRON_SECRET agora?"; then
  SEGREDO=$(openssl rand -hex 32)
  if copiar "$SEGREDO"; then
    say "✓ Segredo gerado e copiado para a área de transferência."
  else
    warn "Sem área de transferência. Segredo (copie agora, não fica gravado): $SEGREDO"
  fi
  open_url "$VERCEL_ENV_URL"
  step "Add Environment Variable:"
  say "    Key:          CRON_SECRET"
  say "    Value:        cole (Ctrl+V)"
  say "    Environments: só Production"
  step "Ligue Sensitive e clique em Save."
  pause "Salvou na Vercel? Pressione Enter"
  SQL_VAULT="delete from vault.secrets where name in ('cron_secret', 'app_url');
select vault.create_secret('${SEGREDO}', 'cron_secret');
select vault.create_secret('${APP_URL}', 'app_url');"
  copiar "$SQL_VAULT" || true
  open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/sql/new"
  step "Cole (Ctrl+V) e rode este SQL no editor (ele guarda o segredo e a URL no Vault do banco):"
  printf '\n'
  printf '%s\n' "$SQL_VAULT" | sed "s/${SEGREDO}/<o segredo, já na área de transferência>/" | sed 's/^/      /'
  printf '\n'
  note "O ticket 04 lê do Vault os nomes cron_secret e app_url."
  pause "Rodou o SQL com sucesso? Pressione Enter"
  copiar "" || true
  unset SEGREDO SQL_VAULT
else
  SKIPPED+=("CRON_SECRET na Vercel e no Vault do Supabase")
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Push: chaves VAPID (só para o ticket 12)"
say "As chaves VAPID identificam o Mural perante os serviços de push do navegador."
if [[ -n "$(_existing NEXT_PUBLIC_VAPID_PUBLIC_KEY || true)" ]]; then
  warn "Já existem chaves VAPID. Gerar novas invalida TODAS as inscrições de push já feitas (cada pessoa terá que ativar de novo)."
fi
if confirm "Gerar as chaves VAPID agora? (diga não se o ticket 12 ainda está longe)"; then
  read -r VAPID_PUBLICA VAPID_PRIVADA < <(node -e 'const c=require("crypto");const k=c.generateKeyPairSync("ec",{namedCurve:"prime256v1"});const p=k.publicKey.export({format:"jwk"});const d=k.privateKey.export({format:"jwk"}).d;const pub=Buffer.concat([Buffer.from([4]),Buffer.from(p.x,"base64url"),Buffer.from(p.y,"base64url")]).toString("base64url");console.log(pub+" "+d)')
  write_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "$VAPID_PUBLICA"
  note "E-mail de contato que acompanha os envios de push (os serviços de push podem usá-lo para falar com você)."
  ask VAPID_EMAIL "E-mail de contato:"
  VAPID_ASSUNTO="mailto:${VAPID_EMAIL}"
  write_env VAPID_SUBJECT "$VAPID_ASSUNTO"
  open_url "$VERCEL_ENV_URL"
  step "Adicione duas variáveis (só Production, sem Sensitive):"
  say "    NEXT_PUBLIC_VAPID_PUBLIC_KEY = $VAPID_PUBLICA"
  say "    VAPID_SUBJECT                = $VAPID_ASSUNTO"
  pause "Salvou as duas? Pressione Enter"
  if copiar "$VAPID_PRIVADA"; then
    say "✓ Chave privada copiada para a área de transferência."
  else
    warn "Sem área de transferência. Chave privada (copie agora, não fica gravada): $VAPID_PRIVADA"
  fi
  step "Adicione a terceira (só Production, ligue Sensitive):"
  say "    VAPID_PRIVATE_KEY = cole (Ctrl+V)"
  pause "Salvou? Pressione Enter"
  copiar "" || true
  unset VAPID_PRIVADA
else
  SKIPPED+=("chaves VAPID (rode este wizard de novo antes do ticket 12)")
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Publicar as variáveis"
say "A Vercel só aplica variáveis novas em deploys novos."
open_url "$VERCEL_ENV_URL"
step "Abra a aba Deployments, no último deploy de produção clique em ⋯ → Redeploy."
step "Espere ficar Ready."
note "Nada disso muda o app ainda: os tickets 04 a 15 é que passam a usar as variáveis."
note "Para desenvolver localmente não precisa de credencial: os testes usam o Drive e o push falsos."
pause

finish
